// TH18 v1.00a Stage 6 Boss5 prelude + BossCard5, source st06bs.ecl.txt:451-493,
// 1223-1407, helper 1408-1456. Spell id 76, source timeout 3600 (B:1250).
// Shell: control enemy at (0,0) with body collision off owns the spell and the
// 120-frame opening buffer; the real boss starts at the common entry (0,128)
// and keeps source hitbox/hurtbox and body collision (B:33-35, B:461 flagClear3).
const TIME_LIMIT: int = 3882;    // 120 buffer + 160 Boss5 prelude + 3600 source timeout + 2
const SOURCE_LIMIT: int = 3600;  // B:1250 slot-0 timeout -> Boss6
const OPENING_BUFFER: int = 120;
const TH18_SHARD: int = 512;     // type 10 Shard, base radius 2.4

// B:1417-1419: ANIM a=1 (birth retreat handled by sh_dist -4), WAIT 20,
// VELTIME type 0x200000 a=60, r=%L, s=-9999994 keeps the bullet angle.
xformdef SHARD_MOTION(target: fx) {
    wait(20);
    step_speed(target, 60 + 65536 * EASE_LINEAR);
}

// B:1408-1455 BossCard5_at. One async instance per source et slot B; each has
// its own target emitter slot 0. A color, C/D base angle, E/F angle steps,
// G radius, H ellipse axis, I axis step, J ratio, K count, L target speed.
async sub at_wave(color: int, c0: angle, d0: angle, de: angle, df: angle,
                  radius: fx, axis: angle, dh: angle, ratio: fx,
                  count: int, target: fx) {
    var rank: int = global(GVAR_RANK);
    // B:1420-1426: Easy scales C/D steps by 4, Normal by 2; H/L unchanged.
    var de_i: int = de as int;
    var df_i: int = df as int;
    if rank == 0 { de_i = de_i * 4; df_i = df_i * 4; }
    if rank == 1 { de_i = de_i * 2; df_i = df_i * 2; }
    var dc: angle = de_i as angle;
    var dd: angle = df_i as angle;
    // B:1442-1450: Easy waits 8, Normal 4, Hard/Lunatic 2.
    var step: int = 2;
    if rank == 0 { step = 8; }
    if rank == 1 { step = 4; }

    sh_reset(0);
    sh_sprite(0, TH18_SHARD, color); // etSprite(B,10,A)
    sh_aim(0, 0);                    // etAim(B,1): fixed direction, N=1
    sh_ring(0, 0);
    sh_count(0, 1, 1);               // etCount(B,1,1)
    sh_speed(0, 1fx, 0fx);           // etSpeed(B,1,1), single layer
    sh_dist(0, -4fx);                // ANIM a=1: -4 * initial speed 1.0
    sh_xform(0, SHARD_MOTION(target));

    var c: angle = c0;
    var d: angle = d0;
    var h: angle = axis;
    for i in 0..count {
        if $frame >= self_int(2) { return; }
        // B:1432 ins_94(M,N,D,G,H,J): phi=D, radius=G, axis=H, ratio=J.
        var t: angle = d - h;
        var u: fx = radius * ratio * cos(t);
        var v: fx = radius * sin(t);
        var m: fx = u * cos(h) - v * sin(h);
        var n: fx = u * sin(h) + v * cos(h);
        // B:1433-1434: H += I and validRad(H) after the point is computed.
        h = h + dh;
        sh_offset(0, m, n);   // etOffset(B,M,N)
        sh_angle(0, c, 0deg); // etAngle(B,C,0)
        sh_fire(0);           // etOn(B)
        // B:1438-1441: C += E, D += F, validRad on both.
        c = c + dc;
        d = d + dd;
        wait(step);
    }
}

// B:1259 moveLimit(0,144,128,64): actual x in [-64,64], y in [112,176];
// direction-selection inner region x +-32, y 128..160.
// B:1401 moveRand(100,0,0.6): speed 0.6*(1-k/100), k=1..100.
// Shared slots: int3 = next step count, fx0/1 = logical unit vector.
sub move_arm(duration: int, speed0: fx) {
    var k: int = self_int(3) + 1;
    set_self_int(3, k);
    var speed: fx = 0fx;
    if k < duration { speed = speed0 * ((duration - k) as fx) / (duration as fx); }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -64fx { nx = -64fx; }
    if nx > 64fx { nx = 64fx; }
    if ny < 112fx { ny = 112fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

// The main task arms k=1 at the moveRand call; this task continues k=2..duration,
// so the first source movement tick is not delayed by the async first-run frame.
async sub move_continue(duration: int, speed0: fx) {
    loop {
        move_arm(duration, speed0);
        if self_int(3) >= duration { return; }
        wait(1);
    }
}

sub card_move_rand() {
    // B:1401 412 moveRand(100,0,0.6): R = pi*U -> BAM r; same native branches.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -32fx {
        a = r / 3;
    } else if $self_x > 32fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 128fx {
        if a < 0 { a = -a; }
    } else if $self_y > 160fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(3, 0);
    move_arm(100, 0.6fx);
}

async sub boss_main() {
    // B:33-35 common boss entry: hurtbox 40x40 -> 20, hitbox 48x48 -> 24.
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    // B:486 movePosTime(90,9,0,128), B:488 wait(160), B:489 moveLimit.
    // Starting from the common entry (0,128) makes the move zero-displacement;
    // its 90/160 timing and the source prelude remain.
    move_to(90, 0fx, 128fx, EASE_QUAD_IN_OUT);
    wait(160);
    // B:1231 timerReset / B:1250 source timeout 3600.
    set_self_int(2, $frame + SOURCE_LIMIT);
    // B:1258-1259: quad-out 60-frame move to (0,144), then limit above.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(60); // B:1261 +60
    wait(60); // B:1265 +60
    // B:1269-1270 source I0/I1, not read by this attack's closure but restored.
    set_self_int(0, 60);
    set_self_int(1, 1);

    var rank: int = global(GVAR_RANK);
    // B:1274-1289 last stack values: L speed 1.8/1.8/1.8/2.5,
    // K count 70/300/300/300 ([-2] = L, [-1] = K).
    var count: int = 300;
    if rank == 0 { count = 70; }
    var target: fx = 1.8fx;
    if rank == 3 { target = 2.5fx; }

    loop {
        if $frame >= self_int(2) { return; }
        // B:1291/1309/1327/1345/1363/1381/1399, initial C=D=90deg+k*360/7,
        // H=D-180deg; E=6deg, F=13deg, I=-2deg, G=100, J=0.5.
        spawn at_wave(4, 16384bam, 16384bam, 6deg, 13deg,
                      100fx, -16384bam, -2deg, 0.5fx, count, target);
        spawn at_wave(6, 25746bam, 25746bam, 6deg, 13deg,
                      100fx, -7022bam, -2deg, 0.5fx, count, target);
        spawn at_wave(8, -30427bam, -30427bam, 6deg, 13deg,
                      100fx, 2341bam, -2deg, 0.5fx, count, target);
        spawn at_wave(10, -21065bam, -21065bam, 6deg, 13deg,
                      100fx, 11703bam, -2deg, 0.5fx, count, target);
        spawn at_wave(13, -11703bam, -11703bam, 6deg, 13deg,
                      100fx, 21065bam, -2deg, 0.5fx, count, target);
        spawn at_wave(14, -2341bam, -2341bam, 6deg, 13deg,
                      100fx, 30427bam, -2deg, 0.5fx, count, target);
        spawn at_wave(2, 7022bam, 7022bam, 6deg, 13deg,
                      100fx, -25746bam, -2deg, 0.5fx, count, target);
        wait(600);
        card_move_rand();
        spawn move_continue(100, 0.6fx);
        wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_main);
    loop { wait(1); }
}

async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, 76, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    loop { wait(600); }
}
